"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[9044],{86216:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"TrainShieldDomeController","desc":"Sole owner of the train shield look and of every shield-hit effect. The\\nshield is a front dome, a tube of beam segments along the train and a rear\\ndome. Both domes are clones of `ReplicatedStorage.ShieldDome` (authored at\\nthe front spot); the tube and rear dome are re-laid whenever\\n`TrainPlatforms.RearX` changes. All of it is client-built. The whole\\nshield shares one visibility. It is hidden by default. It flashes on each\\n`TrainShieldHit` (with a burst sized by the hit\'s severity), reveals itself\\nat random intervals, flickers out when the shield breaks and flickers back\\nin when it reboots. Damage sources never draw shield effects themselves:\\nthey pass `{ Position, Severity }` to `TrainShieldManager.ApplyDamage`.\\nSee the Train Shield docs page, \\"Dome\\".","realm":["Client"],"source":{"line":18,"path":"src/StarterPlayer/StarterPlayerScripts/TrainShieldDomeController.client.luau"}}')}}]);